


/** Merchant-issued purchased gift card. Posted balance includes reserved value; available value is balance minus reservations. Frozen value remains part of outstanding liability. Gift cards are independent resources and cannot be transferred across merchants or currencies. */ export type GiftCard = { /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "available_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "balance_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** RFC3339 timestamp. Format: date-time. */ "created_at": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); "customer_id": string | null; /** Caller-owned identifier for this resource in an external system. minLength: 1. maxLength: 255. */ "external_reference_id": string | null; "gift_card_id": string; "last_characters": string; /** RFC3339 timestamp. Format: date-time. */ "last_loaded_at": string | null; /** RFC3339 timestamp. Format: date-time. */ "last_redeemed_at": string | null; "merchant_id": string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "reserved_money": { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; "status": "pending" | "active" | "frozen" | "closed" | (string & {}); "supported_actions": Array<"freeze" | "unfreeze" | "close" | (string & {})>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "version": string; };
